/* M2.2 Program 142A — Generation Reconciliation Reconstruction. Read-only. */
WITH r AS(SELECT run_id,run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1),c AS(SELECT * FROM msbf_ctl.m2_2_pricing_structure_contract_registry WHERE module1_run_id=(SELECT run_id FROM r))
SELECT r.run_status,c.contract_status,c.policy_rows,c.template_rows,c.reason_rows,c.disposition_rows,c.request_snapshot_rows,c.request_latest_rows,c.request_archive_rows,c.candidate_rows,c.pricing_snapshot_rows,c.pricing_latest_rows,c.pricing_archive_rows,c.comparison_rows,c.canonical_entities,c.policy_set_hash,c.template_set_hash,c.reason_set_hash,c.disposition_set_hash,c.request_snapshot_set_hash,c.request_latest_set_hash,c.request_archive_set_hash,c.candidate_set_hash,c.pricing_snapshot_set_hash,c.pricing_latest_set_hash,c.pricing_archive_set_hash,c.request_contract_set_hash,c.pricing_contract_set_hash,c.combined_set_hash,
CASE WHEN r.run_status IN('M2_2_GENERATED','M2_2_VALIDATED','M2_2_ACCEPTED') AND c.contract_status IN('GENERATED','VALIDATED','ACCEPTED') AND c.request_snapshot_rows=750 AND c.candidate_rows=557 AND c.pricing_snapshot_rows=1500 AND c.comparison_rows=750 AND c.canonical_entities=7336 AND c.combined_set_hash IS NOT NULL THEN 'PASS' ELSE 'FAIL' END AS generation_reconciliation_status FROM r CROSS JOIN c;
